import{_ as p,r as n,o,c as l,e as a,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Настройки темы - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как настраивать функции управления темами.","frontmatter":{"subtitle":"Узнайте, как настраивать функции управления темами."},"headers":[{"level":2,"title":"Информационный файл темы","slug":"информационныи-фаил-темы","link":"#информационныи-фаил-темы","children":[]},{"level":2,"title":"Файл версий","slug":"фаил-версии","link":"#фаил-версии","children":[]},{"level":2,"title":"Изображение предпросмотра темы","slug":"изображение-предпросмотра-темы","link":"#изображение-предпросмотра-темы","children":[]},{"level":2,"title":"Зависимости темы","slug":"зависимости-темы","link":"#зависимости-темы","children":[]},{"level":2,"title":"Кастомизация темы","slug":"кастомизация-темы","link":"#кастомизация-темы","children":[{"level":3,"title":"Использование данных темы в CSS","slug":"использование-данных-темы-в-css","link":"#использование-данных-темы-в-css","children":[]},{"level":3,"title":"Использование данных темы с объединёнными ресурсами","slug":"использование-данных-темы-с-объединенными-ресурсами","link":"#использование-данных-темы-с-объединенными-ресурсами","children":[]}]}],"relativePath":"3.x/ru/cms/themes/settings.md","filePath":"3.x/ru/cms/themes/settings.md"}'),u={name:"3.x/ru/cms/themes/settings.md"};function i(k,s,d,g,m,h){const t=n("pre-heading"),e=n("post-heading");return o(),l("div",null,[a(t),s[0]||(s[0]=c("h1",null,"Настройки темы",-1)),a(e),s[1]||(s[1]=r(`<p>Директория темы может включать файлы <strong>theme.yaml</strong>, <strong>version.yaml</strong> и <strong>assets/images/theme-preview.png</strong>. Эти файлы необязательны для локальной разработки, но обязательны для тем, публикуемых на маркетплейсе October CMS.</p><h2 id="информационныи-фаил-темы"><a href="#информационныи-фаил-темы" class="header-anchor">#</a> Информационный файл темы</h2><p>Информационный файл темы <strong>theme.yaml</strong> содержит описание темы, имя автора, URL веб-сайта автора и другую информацию. Файл должен быть размещён в корневой директории темы:</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       ├── pages
|       ├── layouts
|       ├── partials
|       ├── content
|       ├── assets
|       └── <code>theme.yaml</code>  <em>← Информационный файл</em></p>
</code></pre><p>В файле <strong>theme.yaml</strong> поддерживаются следующие поля:</p><div class="table"><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>задаёт имя темы, обязательное.</td></tr><tr><td><strong>author</strong></td><td>задаёт имя автора, обязательное.</td></tr><tr><td><strong>homepage</strong></td><td>задаёт URL веб-сайта автора, обязательное.</td></tr><tr><td><strong>description</strong></td><td>описание темы, обязательное.</td></tr><tr><td><strong>previewImage</strong></td><td>пользовательское изображение предпросмотра, путь относительно директории темы, например: <code>assets/images/preview.png</code>, необязательное.</td></tr><tr><td><strong>code</strong></td><td>код темы, необязательное. Значение используется на маркетплейсе October CMS для инициализации кода темы.</td></tr><tr><td><strong>authorCode</strong></td><td>код автора темы, необязательное. Значение используется на маркетплейсе October CMS для определения владельца темы.</td></tr><tr><td><strong>form</strong></td><td>массив конфигурации или ссылка на файл определения полей формы, используется для кастомизации темы, необязательное.</td></tr><tr><td><strong>require</strong></td><td>массив имён плагинов, используемых в качестве зависимостей темы, необязательное.</td></tr></tbody></table></div><p>Пример информационного файла темы:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> <span class="token string">&quot;October CMS Demo&quot;</span>
<span class="token key atrule">description</span><span class="token punctuation">:</span> <span class="token string">&quot;Demonstrates the basic concepts of the front-end theming.&quot;</span>
<span class="token key atrule">author</span><span class="token punctuation">:</span> <span class="token string">&quot;October CMS&quot;</span>
<span class="token key atrule">homepage</span><span class="token punctuation">:</span> <span class="token string">&quot;https://octobercms.com&quot;</span>
<span class="token key atrule">code</span><span class="token punctuation">:</span> <span class="token string">&quot;Demo&quot;</span>
<span class="token key atrule">authorCode</span><span class="token punctuation">:</span> <span class="token string">&quot;Acme&quot;</span>
</code></pre></div><h2 id="фаил-версии"><a href="#фаил-версии" class="header-anchor">#</a> Файл версий</h2><p>Файл версий темы <strong>version.yaml</strong> определяет текущую версию темы и журнал изменений. Файл должен быть размещён в корневой директории темы.</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       ├── ...
|       └── theme.yaml
|       └── <code>version.yaml</code>  <em>← Файл версий</em></p>
</code></pre><p>Файл имеет следующий формат.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">v1.0.1</span><span class="token punctuation">:</span> Theme initialization
<span class="token key atrule">v1.0.2</span><span class="token punctuation">:</span> Added more features
<span class="token key atrule">v1.0.3</span><span class="token punctuation">:</span> Some features are removed
</code></pre></div><h2 id="изображение-предпросмотра-темы"><a href="#изображение-предпросмотра-темы" class="header-anchor">#</a> Изображение предпросмотра темы</h2><p>Изображение предпросмотра темы используется в селекторе тем в панели администрирования. Файл изображения <strong>theme-preview.png</strong> должен быть размещён в директории <strong>assets/images</strong> темы:</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       ├── ...
|       └── assets
|           └── images
|               └── <code>theme-preview.png</code>  <em>← Изображение предпросмотра</em></p>
</code></pre><p>Ширина изображения должна быть не менее 600px. Идеальное соотношение сторон — 1.5, например 600x400px.</p><h2 id="зависимости-темы"><a href="#зависимости-темы" class="header-anchor">#</a> Зависимости темы</h2><p>Тема может зависеть от плагинов, для чего необходимо определить параметр <strong>require</strong> в информационном файле темы. Параметр должен содержать массив имён плагинов, являющихся обязательными. Тема, зависящая от <strong>Acme.Blog</strong> и <strong>Acme.User</strong>, может определить это требование следующим образом:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> <span class="token string">&quot;October CMS Demo&quot;</span>
<span class="token comment"># [...]</span>

<span class="token key atrule">require</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> <span class="token string">&quot;Acme.User&quot;</span>
    <span class="token punctuation">-</span> <span class="token string">&quot;Acme.Blog&quot;</span>
</code></pre></div><p>При первой установке темы система попытается одновременно установить требуемые плагины. Для более удобного процесса рассмотрите возможность <a href="./../../extend/resources/publishing-packages.html">добавления этих плагинов в список зависимостей Composer</a>.</p><h2 id="кастомизация-темы"><a href="#кастомизация-темы" class="header-anchor">#</a> Кастомизация темы</h2><p>Темы могут поддерживать конфигурационные значения, если определить ключ <code>form</code> в информационном файле темы. Этот ключ должен содержать массив конфигурации или ссылку на файл определения полей формы, подробнее см. в разделе <a href="./../../element/form-fields.html">определение полей формы</a>.</p><p>Ниже приведён пример определения поля конфигурации для имени сайта под названием <strong>site_name</strong>:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> My Theme
<span class="token comment"># [...]</span>

<span class="token key atrule">form</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token key atrule">site_name</span><span class="token punctuation">:</span>
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Site name
            <span class="token key atrule">comment</span><span class="token punctuation">:</span> The website name as it should appear on the front<span class="token punctuation">-</span>end
            <span class="token key atrule">default</span><span class="token punctuation">:</span> My Amazing Site<span class="token tag">!</span>
</code></pre></div><p>Доступ к значению можно получить в любом шаблоне темы с помощью <a href="./../../markup/property/this-theme.html">глобальной Twig-переменной</a> <code>this.theme</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Welcome to <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> this<span class="token punctuation">.</span>theme<span class="token punctuation">.</span>site_name <span class="token delimiter punctuation">}}</span></span>!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Конфигурацию также можно определить в отдельном файле, путь к которому указывается относительно темы. Следующее определение загружает поля формы из файла <strong>config/fields.yaml</strong> внутри темы.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> My Theme
<span class="token comment"># [...]</span>

<span class="token key atrule">form</span><span class="token punctuation">:</span> config/fields.yaml
</code></pre></div><p><strong>themes/demo/config/fields.yaml</strong>:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">site_name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Site name
        <span class="token key atrule">comment</span><span class="token punctuation">:</span> The website name as it should appear on the front<span class="token punctuation">-</span>end
        <span class="token key atrule">default</span><span class="token punctuation">:</span> My Amazing Site<span class="token tag">!</span>
</code></pre></div><h3 id="использование-данных-темы-в-css"><a href="#использование-данных-темы-в-css" class="header-anchor">#</a> Использование данных темы в CSS</h3><p>Иногда необходимо включить визуальные настройки в таблицу стилей темы. Для этого можно использовать пользовательские свойства CSS (переменные). В следующем примере мы используем <a href="./../../element/form/widget-colorpicker.html">поле типа Color Picker</a> для задания пользовательского цвета ссылок.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">form</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>

        <span class="token key atrule">link_color</span><span class="token punctuation">:</span>
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Link color
            <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
</code></pre></div><p>На основе приведённого примера можно определить <a href="./partials.html">CMS-фрагмент</a>, который передаёт выбранное значение в CSS с помощью локальной таблицы стилей. Фрагмент затем подключается в <a href="./layouts.html">макете темы</a> внутри тега <code>&lt;head&gt;</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>style</span><span class="token punctuation">&gt;</span></span><span class="token style"><span class="token language-css">
    <span class="token selector">:root</span> <span class="token punctuation">{</span>
        <span class="token selector">--my-color:</span> <span class="token punctuation">{</span><span class="token punctuation">{</span> this.theme.link_color <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>style</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>Имена пользовательских свойств чувствительны к регистру, поэтому <code>--my-color</code> будет считаться отдельным пользовательским свойством от <code>--My-color</code>.</p></div><p>Теперь в вашей таблице стилей пользовательское свойство может использоваться в любом месте — достаточно указать имя пользовательского свойства внутри функции <code>var()</code> вместо обычного значения свойства.</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">a</span> <span class="token punctuation">{</span>
    <span class="token property">color</span><span class="token punctuation">:</span> <span class="token function">var</span><span class="token punctuation">(</span>--my-color<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="использование-данных-темы-с-объединенными-ресурсами"><a href="#использование-данных-темы-с-объединенными-ресурсами" class="header-anchor">#</a> Использование данных темы с объединёнными ресурсами</h3><p>Ресурсы, объединённые с помощью <a href="./../markup/filter-theme.html">фильтра и комбинатора</a> <code>|theme</code>, могут получать значения, передаваемые в поддерживаемые фильтры, такие как фильтр LESS. Просто укажите параметр <code>assetVar</code> при определении поля формы — значение должно содержать желаемое имя переменной.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">form</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>

        <span class="token key atrule">link_color</span><span class="token punctuation">:</span>
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Link color
            <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
            <span class="token key atrule">assetVar</span><span class="token punctuation">:</span> <span class="token string">&#39;link-color&#39;</span>
</code></pre></div><p>В приведённом выше примере выбранное значение цвета будет доступно внутри LESS-файла как <code>@link-color</code>. Предположим, у нас есть следующая ссылка на таблицу стилей:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token punctuation">[</span><span class="token string"><span class="token punctuation">&#39;</span>assets/less/theme.less<span class="token punctuation">&#39;</span></span><span class="token punctuation">]</span><span class="token operator">|</span>theme <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Пример содержимого файла <strong>themes/yourtheme/assets/less/theme.less</strong>:</p><div class="language-less extra-class"><pre class="language-less"><code><span class="token selector">a</span> <span class="token punctuation">{</span> <span class="token property">color</span><span class="token punctuation">:</span> <span class="token variable">@link-color</span> <span class="token punctuation">}</span>
</code></pre></div>`,46))])}const f=p(u,[["render",i]]);export{v as __pageData,f as default};
